WITH mentions AS (SELECT UNNEST([{'id': t.start_id, 'nm': t.start_name, 'ty': t.start_type, 'of_json': t.start_of}, {'id': t.end_id, 'nm': t.end_name, 'ty': t.end_type, 'of_json': t.end_of}]) AS m FROM "@receipt-triples:output" t) SELECT m.id AS __corvic_surrogate_id, m.id AS node_id, 'Receipt' AS node_type, min(m.nm) AS name, min(json_extract_string(m.of_json, '$.date')) AS date, TRY_CAST(min(json_extract_string(m.of_json, '$.total')) AS DOUBLE) AS total, count(*) AS mention_count FROM mentions WHERE m.ty = 'Receipt' AND m.id IS NOT NULL AND m.id <> '' GROUP BY m.id